			function onCbx1ValueChange(e){
			    var cbx1 = e.control;
			    
			    var sAtendDayCnt = 0; // 총점
			    var dsRelevaEvlList = app.lookup("dsRelevaEvlList");    
			    for(var i=0; i<dsRelevaEvlList.getRowCount(); i++) {
			        if(dsRelevaEvlList.getValue(i,"CHK") == "true"){
			            sAtendDayCnt += cpr.utils.Util.toNumber(dsRelevaEvlList.getValue(i,"CHKLST_SCORE")) 
			        }
			    }
			        
			   app.lookup("dmRelevaEvlBassInfo").setValue("EVL_SUM_SCORE", sAtendDayCnt);
			   util.Control.redraw(app, "opt8");
			}

